package com.acme.search;

import javax.ws.rs.GET;
import javax.ws.rs.Path;
import javax.ws.rs.QueryParam;
import javax.ws.rs.Produces;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import java.util.regex.Pattern;
import java.util.regex.Matcher;
import java.util.ArrayList;
import java.util.List;
import java.io.File;
import java.io.FileWriter;
import java.io.IOException;

@Path("/api/search")
public class SearchResource {

    // Pattern to validate and extract search terms - supports quoted phrases
    // and boolean operators like AND, OR, NOT
    private static final Pattern SEARCH_PATTERN = Pattern.compile(
        "^(\"[^\"]*\"|\\w+)(\\s+(AND|OR|NOT)\\s+(\"[^\"]*\"|\\w+))*$"
    );

    // Pattern to sanitize input - remove potentially dangerous characters
    // while preserving search operator syntax
    private static final Pattern SANITIZE_PATTERN = Pattern.compile(
        "([a-zA-Z0-9]+\\s*)+([+\\-&|!(){}\\[\\]^~*?:\\\\/@]\\s*)*"
    );

    private static final String QUERY_LOG_PATH = "/var/log/search/queries.log";

    @GET
    @Produces(MediaType.APPLICATION_JSON)
    public Response search(@QueryParam("q") String query,
                          @QueryParam("strict") boolean strictMode) {
        if (query == null || query.isEmpty()) {
            return Response.status(400)
                .entity("{\"error\": \"Missing query parameter 'q'\"}")
                .build();
        }

        if (query.length() > 2048) {
            return Response.status(400)
                .entity("{\"error\": \"Query too long\"}")
                .build();
        }

        // Log query for analytics (best-effort)
        logQuery(query);

        // Validate query syntax in strict mode
        if (strictMode) {
            Matcher validator = SEARCH_PATTERN.matcher(query);
            if (!validator.matches()) {
                return Response.status(400)
                    .entity("{\"error\": \"Invalid search syntax\"}")
                    .build();
            }
        }

        // Sanitize the query
        String sanitized = sanitizeQuery(query);

        // Execute search (simplified - would normally call search backend)
        List<String> results = executeSearch(sanitized);

        return Response.ok()
            .entity(formatResults(results, query))
            .build();
    }

    private String sanitizeQuery(String input) {
        Matcher m = SANITIZE_PATTERN.matcher(input);
        StringBuilder sb = new StringBuilder();
        while (m.find()) {
            sb.append(m.group());
        }
        return sb.toString().trim();
    }

    private void logQuery(String query) {
        try {
            File logFile = new File(QUERY_LOG_PATH);
            logFile.getParentFile().mkdirs();
            FileWriter fw = new FileWriter(logFile, true);
            fw.write(System.currentTimeMillis() + "\t" + query + "\n");
            fw.close();
        } catch (IOException e) {
            // Logging is best-effort, swallow exception
        }
    }

    private List<String> executeSearch(String query) {
        // Simulated search results
        List<String> results = new ArrayList<>();
        results.add("Result 1 for: " + query);
        results.add("Result 2 for: " + query);
        return results;
    }

    private String formatResults(List<String> results, String originalQuery) {
        StringBuilder json = new StringBuilder();
        json.append("{\"query\": \"").append(escapeJson(originalQuery)).append("\",");
        json.append("\"results\": [");
        for (int i = 0; i < results.size(); i++) {
            json.append("\"").append(escapeJson(results.get(i))).append("\"");
            if (i < results.size() - 1) json.append(",");
        }
        json.append("]}");
        return json.toString();
    }

    private String escapeJson(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"");
    }
}
